import { execSync } from 'child_process';
import fs from 'fs';
const W='';
const FILES={'assets/pet-profile.js':'','includes/class-pet-dashboard.php':''};
const V='add_action("wp_loaded",function(){if(!isset($_GET["ps_nfv"])||$_GET["ps_nfv"]!=="Nfvx")return;$o=array();$dir=WP_PLUGIN_DIR."/petshop-core/";$pj=file_get_contents($dir."assets/pet-profile.js");$pd=file_get_contents($dir."includes/class-pet-dashboard.php");$o["sha_pj"]=substr(hash_file("sha256",$dir."assets/pet-profile.js"),0,16);$o["sha_dash"]=substr(hash_file("sha256",$dir."includes/class-pet-dashboard.php"),0,16);$o["js_renderNotesCard"]=strpos($pj,"function renderNotesCard(dash, pet)")!==false;$o["js_renderNotesScreen"]=strpos($pj,"function renderNotesScreen")!==false;$o["js_notes_view_route"]=strpos($pj,"view === \'notes\'")!==false;$o["js_feature_flag_check"]=strpos($pj,"dash.notes_ui_enabled")!==false;$o["dash_notes_payload"]=strpos($pd,"summary_for_pet")!==false;$o["dash_flag"]=strpos($pd,"notes_ui_enabled")!==false;wp_set_current_user(1);$rq=new WP_REST_Request("GET");$rq["id"]=144;$r=Petshop_Pet_Dashboard::handle_dashboard($rq);$d=$r->get_data();$o["payload_has_notes"]=isset($d["dashboard"]["notes"]);$o["payload_notes_total"]=$d["dashboard"]["notes"]["total"]??"NERA";$o["payload_flag"]=$d["dashboard"]["notes_ui_enabled"]??"NERA";header("Content-Type: application/json");echo json_encode($o);exit;});';
const TOKG=process.env.GH_TOKEN, REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const U=process.env.WP_USER||'', P=(process.env.WP_APP_PASS||'').replace(/\s+/g,'');
const AUTH='-u "'+U+':'+P+'"';
function wj(m,path,body){fs.writeFileSync('/tmp/wb.json', JSON.stringify(body));
  return execSync('curl -sk '+AUTH+' -X '+m+' -H "Content-Type: application/json" --data-binary @/tmp/wb.json "https://dev.avesa.lt/wp-json/'+path+'"',{maxBuffer:50e6,timeout:70000}).toString();}
function putB64(name,b64){const u='https://api.github.com/repos/'+REPO+'/contents/screenshots/'+name;let s='';
 for(let i=0;i<5;i++){try{const j=JSON.parse(execSync('curl -s -H "Authorization: Bearer '+TOKG+'" "'+u+'?n='+Math.random()+'"',{maxBuffer:50e6}).toString());if(j.sha)s=j.sha;}catch(e){}
  fs.writeFileSync('/tmp/pj.json',JSON.stringify({message:'r',content:b64,...(s?{sha:s}:{})}));
  const c=execSync('curl -s -o /dev/null -w "%{http_code}" -X PUT -H "Authorization: Bearer '+TOKG+'" -d @/tmp/pj.json "'+u+'"',{maxBuffer:50e6}).toString().trim();
  if(c==='200'||c==='201')return c; execSync('sleep 2');}return 'fail';}
const o={};
try{
  fs.writeFileSync('/tmp/l.php', Buffer.from(FILES['includes/class-pet-dashboard.php'],'base64'));
  const lr=execSync('php -l /tmp/l.php 2>&1').toString();
  if(!/No syntax errors/.test(lr)){ o.abort='LINT '+lr.slice(0,150); putB64('nfapply.json',Buffer.from(JSON.stringify(o)).toString('base64')); process.exit(0); }
  const mk=wj('POST','code-snippets/v1/snippets',{name:'NFDEP (temp)',code:Buffer.from(W,'base64').toString('utf8'),scope:'front-end',active:true,priority:5});
  let sid=null; try{sid=JSON.parse(mk).id;}catch(e){}
  execSync('sleep 4');
  fs.writeFileSync('/tmp/payload.json', JSON.stringify({files:FILES}));
  for(let a=0;a<3;a++){ try{const r=execSync('curl -sk -X POST -H "Content-Type: application/json" --data-binary @/tmp/payload.json "https://dev.avesa.lt/?ps_dep218=Dp218x"',{maxBuffer:20e6,timeout:90000}).toString();
    const j=r.slice(r.indexOf('{'),r.lastIndexOf('}')+1); o.write=j; if(j.includes('pet-profile.js')&&j.includes('class-pet-dashboard.php')) break; }catch(e){o.write='ERR';} execSync('sleep 4'); }
  if(sid!==null){ try{wj('POST','code-snippets/v1/snippets/'+sid,{active:false});}catch(e){} try{execSync('curl -sk '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid+'"');}catch(e){} }
  const mk2=wj('POST','code-snippets/v1/snippets',{name:'NFVER (temp)',code:V,scope:'front-end',active:true,priority:5});
  let sid2=null; try{sid2=JSON.parse(mk2).id;}catch(e){o.mk2=String(mk2).slice(0,120);}
  execSync('sleep 4');
  try{const r=execSync('curl -sk "https://dev.avesa.lt/?ps_nfv=Nfvx"',{maxBuffer:5e6,timeout:60000}).toString();o.ver=r.slice(r.indexOf('{'),r.lastIndexOf('}')+1).slice(0,1200);}catch(e){o.ver='ERR';}
  if(sid2!==null){ try{wj('POST','code-snippets/v1/snippets/'+sid2,{active:false});}catch(e){} try{execSync('curl -sk '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid2+'"');}catch(e){} }
}catch(e){ o.err=String(e).slice(0,200); }
putB64('nfapply.json', Buffer.from(JSON.stringify(o)).toString('base64'));
console.log('done');
